        private static bool BuildSetupNotice(VisualElement host, UnityMcpWelcomeContext context)
        {
            string method = context.Config.setupStatus;
            if (string.IsNullOrEmpty(method)) return false;
            int split = method.LastIndexOf('.');
            if (split < 1) return false;
            string message = null;
            foreach (Assembly assembly in UnityMcpWelcomeServices.LoadedAssemblies())
            {
                Type type = assembly.GetType(method.Substring(0, split));
                if (type == null) continue;
                MethodInfo callback = type.GetMethod(method.Substring(split + 1), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic,
                    null, Type.EmptyTypes, null);
                if (callback?.ReturnType != typeof(string)) break;
                try { message = (string)callback.Invoke(null, null); }
                catch (Exception) { message = "The project setup check could not finish. Open the Console for details."; }
                break;
            }
            if (string.IsNullOrEmpty(message)) return false;
            VisualElement band = Band(host, "warn", "Finish project setup", message);
            UnityMcpAction action = context.Config.setupAction;
            if (UnityMcpWelcomeServices.IsSet(action))
            {
                VisualElement button = Clickable(() => UnityMcpWelcomeServices.Run(context, action, null, null), "abw-btn");
                button.Add(new Label(action.label));
                band.Add(button);
            }
            return true;
        }
    }
